import json
from itertools import product

def cross(a, b):
    return (a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0])

def dot(a, b):
    return sum(x*y for x, y in zip(a, b))

def par(a, b):
    c = cross(a, b)
    return c == (0, 0, 0)

V = [v for v in product((-1, 0, 1), repeat=3) if v != (0, 0, 0)]
counter = {k: None for k in "ABCD"}
holds = {k: True for k in "ABCD"}

for na, nb, ng in product(V, repeat=3):
    # A: alpha ⊥ beta, l = intersection direction, m ⊥ l (m not necessarily in alpha)
    if dot(na, nb) == 0:
        l = cross(na, nb)
        for d in V:
            if dot(d, l) == 0 and not par(d, nb):
                holds["A"] = False
                counter["A"] = counter["A"] or (na, nb, d)
    # B: m = alpha∩gamma direction
