        m = cross(na, ng)
        if not par(m, nb):
            holds["B"] = False
            counter["B"] = counter["B"] or (na, nb, ng)
    # C: m ⊥ alpha
    if dot(na, ng) == 0 and dot(nb, ng) == 0:
        m = na
        if not par(m, nb):
            holds["C"] = False
            counter["C"] = counter["C"] or (na, nb, ng)
    # D: n ⊥ alpha, n ⊥ beta, m ⊥ alpha (n direction = ng here)
    if par(ng, na) and par(ng, nb):
        m = na
        if not par(m, nb):
            holds["D"] = False
            counter["D"] = counter["D"] or (na, nb, ng)

ans = [k for k in "ABCD" if holds[k]]
